from __future__ import annotations

import math
import re
from typing import Any, Callable, Optional, Tuple

import numpy as np
import pandas as pd

from csv_trimming.logger import get_logger


LOGGER = get_logger(__name__)

SPACES = [" ", "\t", "\n", "\r", "\v", "\f"]
UNICODE_SPACES = [
    "\u00a0",
    "\u1680",
    "\u2000",
    "\u2001",
    "\u2002",
    "\u2003",
    "\u2004",
    "\u2005",
    "\u2006",
    "\u2007",
    "\u2008",
    "\u2009",
    "\u200a",
    "\u2028",
    "\u2029",
    "\u202f",
    "\u205f",
    "\u3000",
    "\ufeff",
    "\u200b",
    "\u2060",
]
NAN_LIKE_ARTIFACTS = [
    "",
    "nan",
    "none",
    "null",
    "nil",
    "na",
    "n/a",
    "#n/a",
    "<na>",
    "nat",
    "not available",
    "missing",
]
UNICODE_NAN_LIKE_ARTIFACTS = [
    "\u2014",
    "\u2013",
]
NAN_LIKE = NAN_LIKE_ARTIFACTS + UNICODE_NAN_LIKE_ARTIFACTS
SPACE_LIKE = sorted(SPACES + UNICODE_SPACES, key=lambda x: -len(x))


def _collapse_spaces(value: str) -> str:
    cleaned = value.replace("\x00", "")
    for space in UNICODE_SPACES:
        cleaned = cleaned.replace(space, " ")
    cleaned = re.sub(r"\s+", " ", cleaned, flags=re.UNICODE)
    return cleaned.strip()


def _stringify(value: Any) -> str:
    if isinstance(value, str):
        return _collapse_spaces(value)
    return _collapse_spaces(str(value))


def is_nan(candidate: Any) -> bool:
    """Return True if the given candidate is NaN-like."""

    if candidate is None:
        return True

    try:
        if pd.isna(candidate):
            return True
    except TypeError:
        pass

    if isinstance(candidate, str):
        normalized = _collapse_spaces(candidate).casefold()
        return normalized in {artifact.casefold() for artifact in NAN_LIKE}

    if isinstance(candidate, (float, np.floating)):
        return math.isnan(candidate)

    return False


def _is_numeric_like(value: Any) -> bool:
    if is_nan(value):
        return False
    if isinstance(value, (int, float, np.number)) and not isinstance(value, bool):
        return True
    if isinstance(value, str):
        normalized = _collapse_spaces(value)
        return bool(re.fullmatch(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)", normalized))
    return False


def _is_default_header(columns: pd.Index) -> bool:
    if isinstance(columns, pd.RangeIndex):
        return True

    if len(columns) == 0:
        return True

    generic = 0
    for position, value in enumerate(columns, start=1):
        if is_nan(value):
            generic += 1
            continue
        text = _stringify(value).casefold()
        if text.startswith("unnamed:"):
            generic += 1
        elif text == str(position - 1):
            generic += 1
        elif text == f"column #{position}":
            generic += 1

    return generic >= max(1, len(columns) // 2)


def _header_candidate_score(values: pd.Series | list[Any] | pd.Index) -> float:
    if isinstance(values, (pd.Series, pd.Index)):
        sequence = values.tolist()
    else:
        sequence = list(values)

    total = len(sequence)
    if total == 0:
        return float("-inf")

    normalized = [_collapse_spaces(v) if isinstance(v, str) else v for v in sequence]
    non_empty = [value for value in normalized if not is_nan(value)]
    if not non_empty:
        return float("-inf")

    as_text = [_stringify(value) for value in non_empty]
    unique_ratio = len(set(text.casefold() for text in as_text)) / len(non_empty)
    text_ratio = sum(not _is_numeric_like(value) for value in non_empty) / len(non_empty)
    completeness = len(non_empty) / total
    return (1.4 * completeness) + unique_ratio + (0.8 * text_ratio)


def _base_header_name(value: Any) -> str:
    text = _stringify(value)
    return re.sub(r"\.duplicated(?:\.\d+)?$", "", text)


def _standardize_headers(values: list[Any]) -> list[str]:
    counts: dict[str, int] = {}
    headers: list[str] = []

    for position, raw in enumerate(values, start=1):
        candidate = _collapse_spaces(raw) if isinstance(raw, str) else _stringify(raw)
        if is_nan(candidate):
            candidate = f"column #{position}"

        if candidate in counts:
            counts[candidate] += 1
            suffix = ".duplicated" if counts[candidate] == 1 else f".duplicated.{counts[candidate]}"
            candidate = f"{candidate}{suffix}"
        else:
            counts[candidate] = 0

        headers.append(candidate)

    return headers


def _copy_with_attrs(csv: pd.DataFrame) -> pd.DataFrame:
    copied = csv.copy()
    copied.attrs = dict(csv.attrs)
    return copied


class CSVTrimmer:
    """Class handling the cleaning up of malformed CSVs using heuristics."""

    def __init__(
        self,
        correlation_callback: Optional[
            Callable[[pd.Series, pd.Series], Tuple[bool, pd.Series]]
        ] = None,
    ):
        """Create new CSVTrimmer object."""

        self._correlation_callback = correlation_callback

    def _mask_edges(self, mask: np.ndarray) -> np.ndarray:
        """Return boolean array with only the True values connected to the sides."""

        edges = np.zeros_like(mask, dtype=bool)
        if mask.size == 0:
            return edges

        left = 0
        while left < mask.size and bool(mask[left]):
            edges[left] = True
            left += 1

        right = mask.size - 1
        while right >= 0 and bool(mask[right]):
            edges[right] = True
            right -= 1

        return edges

    def trim_padding(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return given CSV with trimmed border rows and columns."""

        cleaned = _copy_with_attrs(csv)
        if cleaned.empty:
            return cleaned

        empties = cleaned.apply(lambda column: column.map(is_nan))
        row_mask = empties.all(axis=1).to_numpy(dtype=bool)
        col_mask = empties.all(axis=0).to_numpy(dtype=bool)

        edge_rows = self._mask_edges(row_mask)
        edge_cols = self._mask_edges(col_mask)

        trimmed = cleaned.loc[~edge_rows, cleaned.columns[~edge_cols]]
        trimmed = trimmed.reset_index(drop=True)
        trimmed.attrs = dict(csv.attrs)
        LOGGER.debug(
            "trim_padding removed %s rows and %s columns",
            int(edge_rows.sum()),
            int(edge_cols.sum()),
        )
        return trimmed

    def restore_header(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return CSV with a restored or standardized header."""

        cleaned = _copy_with_attrs(csv)
        if cleaned.shape[1] == 0:
            return cleaned.reset_index(drop=True)

        header_score = _header_candidate_score(cleaned.columns)
        default_header = _is_default_header(cleaned.columns)

        best_index: Optional[int] = None
        best_score = float("-inf")
        for offset, (_, row) in enumerate(cleaned.head(min(len(cleaned), 8)).iterrows()):
            score = _header_candidate_score(row)
            if score > best_score:
                best_index = offset
                best_score = score

        should_restore = False
        if best_index is not None and len(cleaned) > 0:
            if default_header:
                should_restore = True
            elif best_score > header_score + 0.35:
                should_restore = True

        if should_restore and best_index is not None:
            raw_header = cleaned.iloc[best_index].tolist()
            headers = _standardize_headers(raw_header)
            restored = cleaned.iloc[best_index + 1 :].copy()
            restored.columns = headers
            restored.attrs = dict(csv.attrs)
            restored.attrs["raw_header"] = raw_header
            LOGGER.debug("restore_header adopted row %s as header", best_index)
            return restored.reset_index(drop=True)

        headers = _standardize_headers(list(cleaned.columns))
        cleaned.columns = headers
        cleaned.attrs["raw_header"] = list(cleaned.columns)
        LOGGER.debug("restore_header kept existing columns")
        return cleaned.reset_index(drop=True)

    def drop_empty_columns(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return DataFrame with removed empty columns."""

        cleaned = _copy_with_attrs(csv)
        if cleaned.shape[1] == 0 or cleaned.shape[0] == 0:
            return cleaned

        keep_mask = ~cleaned.apply(lambda column: column.map(is_nan).all(), axis=0)
        result = cleaned.loc[:, keep_mask]
        result.attrs = dict(csv.attrs)
        LOGGER.debug("drop_empty_columns removed %s columns", int((~keep_mask).sum()))
        return result

    def drop_duplicated_schema(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return DataFrame with removed duplicated schema rows."""

        cleaned = _copy_with_attrs(csv)
        if cleaned.empty or cleaned.shape[1] == 0:
            return cleaned

        expected = [_base_header_name(column).casefold() for column in cleaned.columns]

        def matches_header(row: pd.Series) -> bool:
            row_values = []
            for value in row.tolist():
                if is_nan(value):
                    row_values.append("")
                else:
                    row_values.append(_stringify(value).casefold())
            return row_values == expected

        keep_rows = ~cleaned.apply(matches_header, axis=1)
        result = cleaned.loc[keep_rows].reset_index(drop=True)
        result.attrs = dict(csv.attrs)
        LOGGER.debug("drop_duplicated_schema removed %s rows", int((~keep_rows).sum()))
        return result

    def drop_empty_rows(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return DataFrame with removed empty rows."""

        cleaned = _copy_with_attrs(csv)
        if cleaned.shape[0] == 0:
            return cleaned

        keep_rows = ~cleaned.apply(lambda row: row.map(is_nan).all(), axis=1)
        result = cleaned.loc[keep_rows].reset_index(drop=True)
        result.attrs = dict(csv.attrs)
        LOGGER.debug("drop_empty_rows removed %s rows", int((~keep_rows).sum()))
        return result

    def _deep_strip(self, string: str):
        """Return string without continuous spaces."""

        if not isinstance(string, str):
            return string
        return _collapse_spaces(string)

    def trim_spaces(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return dataframe without multiple spaces."""

        cleaned = _copy_with_attrs(csv)
        if cleaned.empty:
            return cleaned

        transformed = cleaned.apply(lambda column: column.map(self._deep_strip))
        transformed.attrs = dict(csv.attrs)
        LOGGER.debug("trim_spaces normalized string values")
        return transformed

    def restore_true_nan(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return CSV with restored true NaN values."""

        cleaned = _copy_with_attrs(csv)
        if cleaned.empty:
            return cleaned

        def normalize(value: Any) -> Any:
            if is_nan(value):
                return np.nan
            return value

        transformed = cleaned.apply(lambda column: column.map(normalize))
        transformed.attrs = dict(csv.attrs)
        LOGGER.debug("restore_true_nan restored NaN-like artifacts")
        return transformed

    def normalize_correlated_rows(self, csv: pd.DataFrame) -> pd.DataFrame:
        """Return normalized correlated rows."""

        cleaned = _copy_with_attrs(csv)
        if self._correlation_callback is None or len(cleaned) < 2:
            return cleaned.reset_index(drop=True)

        rows: list[pd.Series] = []
        index = 0
        while index < len(cleaned):
            current = cleaned.iloc[index].copy()
            if index + 1 < len(cleaned):
                next_row = cleaned.iloc[index + 1].copy()
                skip_next, merged = self._correlation_callback(current, next_row)
                rows.append(merged)
                index += 2 if skip_next else 1
            else:
                rows.append(current)
                index += 1

        result = pd.DataFrame(rows)
        result.attrs = dict(csv.attrs)
        LOGGER.debug("normalize_correlated_rows produced %s rows", len(result))
        return result.reset_index(drop=True)

    def trim(
        self,
        csv: pd.DataFrame,
        restore_header: bool = True,
        drop_padding: bool = True,
        drop_duplicated_schema: bool = True,
    ) -> pd.DataFrame:
        """Return sanitized version of given dataframe."""

        cleaned = _copy_with_attrs(csv)
        LOGGER.info("starting trim on shape=%s", cleaned.shape)
        cleaned = self.trim_spaces(cleaned)
        if drop_padding:
            cleaned = self.trim_padding(cleaned)
        cleaned = self.drop_empty_rows(cleaned)
        if restore_header:
            cleaned = self.restore_header(cleaned)
        cleaned = self.restore_true_nan(cleaned)
        cleaned = self.normalize_correlated_rows(cleaned)
        cleaned = self.drop_empty_columns(cleaned)
        if drop_duplicated_schema:
            cleaned = self.drop_duplicated_schema(cleaned)

        cleaned = cleaned.reset_index(drop=True)
        cleaned.index.name = None
        cleaned.columns.name = None
        LOGGER.info("finished trim with shape=%s", cleaned.shape)
        return cleaned


def trim(
    csv: pd.DataFrame,
    restore_header: bool = True,
    drop_padding: bool = True,
    drop_duplicated_schema: bool = True,
    correlation_callback: Optional[Callable[[pd.Series, pd.Series], Tuple[bool, pd.Series]]] = None,
) -> pd.DataFrame:
    """Convenience wrapper around :class:`CSVTrimmer`."""

    return CSVTrimmer(correlation_callback=correlation_callback).trim(
        csv,
        restore_header=restore_header,
        drop_padding=drop_padding,
        drop_duplicated_schema=drop_duplicated_schema,
    )


__all__ = [
    "CSVTrimmer",
    "NAN_LIKE",
    "SPACE_LIKE",
    "is_nan",
    "trim",
]

