from __future__ import annotations

import pandas as pd

from csv_trimming import CSVTrimmer


def test_normalize_correlated_rows_with_callback():
    csv = pd.DataFrame(
        {
            "name": ["Ada", None, "Grace"],
            "surname": [None, "Lovelace", "Hopper"],
            "role": ["Analyst", None, "Admiral"],
        }
    )

    def callback(current_row: pd.Series, next_row: pd.Series):
        if pd.isna(current_row["surname"]) and pd.isna(next_row["name"]):
            merged = current_row.copy()
            merged["surname"] = next_row["surname"]
            merged["role"] = current_row["role"]
            return True, merged
        return False, current_row

    result = CSVTrimmer(correlation_callback=callback).normalize_correlated_rows(csv)

    expected = pd.DataFrame(
        [
            {"name": "Ada", "surname": "Lovelace", "role": "Analyst"},
            {"name": "Grace", "surname": "Hopper", "role": "Admiral"},
        ]
    )
    pd.testing.assert_frame_equal(result, expected)


def test_trim_pipeline_with_correlation():
    csv = pd.DataFrame(
        [
            [" name ", "surname", "role"],
            ["Ada", None, "Analyst"],
            [None, "Lovelace", None],
            ["Grace", "Hopper", "Admiral"],
        ]
    )

    def callback(current_row: pd.Series, next_row: pd.Series):
        if pd.isna(current_row["surname"]) and pd.isna(next_row["name"]):
            merged = current_row.copy()
            merged["surname"] = next_row["surname"]
            return True, merged
        return False, current_row

    result = CSVTrimmer(correlation_callback=callback).trim(csv)

    expected = pd.DataFrame(
        [
            {"name": "Ada", "surname": "Lovelace", "role": "Analyst"},
            {"name": "Grace", "surname": "Hopper", "role": "Admiral"},
        ]
    )
    pd.testing.assert_frame_equal(result, expected)
